import { firstNames } from './names.js';
import { documentVocabulary } from './document-vocabulary.js';

const boundary = '[\\p{L}\\p{M}\\p{N}_]';
const proper = "\\p{Lu}[\\p{L}\\p{M}’'-]{1,47}";
const name = `${proper}(?:[ \\t]+${proper}){0,3}`;
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blocked =
