pypi = json.loads((cache / 'pypi.json').read_text())
actions = json.loads((cache / 'actions.json').read_text())
nlp_names = {'@nlpjs/core', '@nlpjs/language-min', '@nlpjs/ner', '@nlpjs/similarity'}

def before(path):
    return subprocess.check_output(['git','show', f'{base}:{path}'], text=True)

def table(name, rows):
    with (output / f'{name}.csv').open('w',newline='') as handle:
        writer = csv.writer(handle, lineterminator='\\n')
        writer.writerow(['dependency', 'baseline', 'registry latest', 'selected', 'location', 'reason', 'registry'])
        writer.writerows(rows)
    print(name, len(rows))

def npm_url(name):
    return f'https://registry.npmjs.org/{quote(name, safe="")}/latest'

def npm_name(location, value):
    return value.get('name') or location.rsplit('node_modules/', 1)[1]

def npm_consumers(packages):
    incoming = defaultdict(set)
    for owner, data in packages.items():
        for field in ['dependencies', 'optionalDependencies', 'peerDependencies', 'devDependencies']:
            for name, constraint in data.get(field, {}).items():
                parent = owner
                while True:
                    key = (parent + '/' if parent else '') + 'node_modules/' + name
                    if key in packages:
                        label = owner.rsplit('node_modules/',1)[-1] or '(manifest)'
                        incoming[key].add(f'{label}@{data.get("version", "workspace")} {constraint}')
                        break
                    if not parent:
                        break
                    parent = parent.rsplit('/node_modules/',1)[0] if '/node_modules/' in parent else ''
    return incoming

for name, filename in [('npm-root','package-lock.json'), ('npm-app','examples/universal-app/package-lock.json'), ('npm-artifact','.github/actions/artifact-transport/package-lock.json')]:
    original = json.loads(before(filename))['packages']
    current = json.loads(Path(filename).read_text())['packages']
    parents = npm_consumers(current)
    rows = []
    for location in sorted(original.keys() | current.keys()):
        if 'node_modules/' not in location or current.get(location, original.get(location)).get('link'):
            continue
        package = npm_name(location, current.get(location, original.get(location)))
        old = original.get(location,{}).get('version','')
        version = current.get(location,{}).get('version','')
        if package not in npm:
            assert current.get(location, original.get(location)).get('resolved', '').startswith('file:'), package
            rows.append((package,old,'local only',version,location,'temp 0.9.4 expects rimraf callbacks. The local adapter delegates to node:fs.rm.','https://github.com/bruce/node-temp/issues/100'))
            continue
