        elif latest == version:
            reason = 'Current.'
        elif package in nlp_names:
            reason = 'Current stable 4.x family. npm latest points to an alpha release.'
        else:
            assert parents[location], (location, package, version, latest)
            reason = 'Upstream consumer range: ' + '; '.join(sorted(parents[location]))
        rows.append((package,old,latest,version,location,reason,npm_url(package)))
    table(name, sorted(rows))

def deno_split(key):
    return re.match(r'^(@[^/]+/[^@]+|[^@]+)@([^_]+)',key).groups()

old = json.loads(before('deno.lock'))['npm']
deno_lock = json.loads(Path('deno.lock').read_text())
new = deno_lock['npm']
old_versions = defaultdict(set)
current_keys = defaultdict(set)
current_base_keys = defaultdict(set)
for loc in old:
    package, version = deno_split(loc)
    old_versions[package].add(version)
for loc in new:
    package, version = deno_split(loc)
    current_keys[package].add(loc)
    current_base_keys[f'{package}@{version}'].add(loc)
deno_parents = defaultdict(set)
for loc, data in new.items():
    for dep in data.get('dependencies', []) + data.get('optionalDependencies', []):
        for target in ({dep} if dep in new else current_keys[dep] | current_base_keys[dep]):
            deno_parents[target].add(loc)
